{"command":"cd /testbed && python3 - <<'EOF'
import os, hashlib, json

DATA = "/testbed/data"

def digest(p):
    with open(p,'rb') as f: return hashlib.sha256(f.read()).hexdigest()

before = {}
for root, dirs, files in os.walk(DATA):
    for name in files:
        p = os.path.join(root, name)
        if name.lower().endswith('.csv'):
            before[p] = (os.path.getsize(p), digest(p))

json.dump({k:v for k,v in before.items()}, open('/tmp/before.json','w'), indent=1)

plan = []
for root in sorted({os.path.dirname(p) for p in before}):
    entries = [(os.path.getsize(p), p, os.path.basename(p)) for p in before if os.path.dirname(p)==root]
    entries.sort(key=lambda e: (e[0], e[2]))          # ascending size, name tie-break
    for i, (size, path, name) in enumerate(entries):
        plan.append((path, os.path.join(root, f"{i}.csv"), size, name))

for src, dst, size, name in plan:
    print(f"{size:>6}  {name:<12} -> {os.path.basename(dst)}")

# two-phase to avoid collisions with existing names
tmp = []
for src, dst, *_ in plan:
    t = src + ".__renametmp__"
    os.rename(src, t); tmp.append((t, dst))
for t, dst in tmp:
    os.rename(t, dst)
print("renamed:", len(tmp))
EOF"}
